#include "../../05-数学/多项式求逆与ln_exp.cpp"
vector<int> slow(vector<int>a,vector<int>b,int n){vector<int>c(n);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size()&&i+j<n;j++)c[i+j]=(c[i+j]+(ll)a[i]*b[j])%P;return c;}
int main(){mt19937 r(131);for(int t=0;t<80;t++){int n=1+r()%35;vector<int>a(n),b(n);for(int &x:a)x=r()%P;for(int &x:b)x=r()%P;int k=r()%6;vector<int>w(n);w[0]=1;for(int i=0;i<k;i++)w=slow(w,a,n);assert(polynomial_power(a,k,n)==w);auto square=slow(a,a,n);vector<int>root;assert(polynomial_sqrt(square,n,root));assert(slow(root,root,n)==square);vector<int>x(n);iota(x.begin(),x.end(),1);PolynomialPoints points(x);auto y=points.evaluate(a);for(int i=0;i<n;i++){ll z=0;for(int j=n-1;j>=0;j--)z=(z*x[i]+a[j])%P;assert(y[i]==z);}assert(points.interpolate(y)==a);b[0]=0;w.assign(n,0);for(int i=n-1;i>=0;i--){w=slow(w,b,n);w[0]=(w[0]+a[i])%P;}assert(polynomial_compose(a,b,n)==w);b.resize(1+r()%n);if(!b.back())b.back()=1;auto [q,rem]=polynomial_divmod(a,b);auto c=slow(q,b,n);for(int i=0;i<(int)rem.size();i++)c[i]=(c[i]+rem[i])%P;assert(c==a);}vector<int>z;assert(!polynomial_sqrt({0,1},5,z));assert(polynomial_power({0,2},ULLONG_MAX,10)==vector<int>(10));assert(polynomial_sqrt({0,0,4},5,z)&&slow(z,z,5)==vector<int>({0,0,4,0,0}));}
